<?php get_header(); ?><main class="section"><div class="container"><h1>سخنرانان</h1><div class="hm-dynamic-grid" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px"><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="hm-theme-notice"><?php if(has_post_thumbnail())the_post_thumbnail('medium'); ?><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></article><?php endwhile;the_posts_pagination();else:?><p>هنوز سخنرانی ثبت نشده است.</p><?php endif; ?></div></div></main><?php get_footer(); ?>